type Produk = { nama: string; harga: number; stok: number };
function ambil<T, K extends keyof T>(obj: T, kunci: K): T[K] {
  return obj[kunci];
}
function urutkan<T>(a: T[], kunci: keyof T): T[] {
  return [...a].sort((x, y) => (x[kunci] < y[kunci] ? -1 : 1));
}
const daftar: Produk[] = [
  { nama: "Teh", harga: 12000, stok: 8 },
  { nama: "Kopi", harga: 18000, stok: 3 },
  { nama: "Jus", harga: 15000, stok: 5 },
];
console.log(ambil(daftar[0], "harga") + 1000);
console.log(urutkan(daftar, "stok").map((p) => p.nama));

