type Barang = { nama: string; stok: number; harga: number };
type KunciAngka<T> = { [K in keyof T]: T[K] extends number ? K : never }[keyof T];
function ambil<T, K extends keyof T>(obj: T, kunci: K): T[K] {
  return obj[kunci];
}
function totalKolom<T>(a: T[], kunci: KunciAngka<T>): number {
  let total = 0;
  for (const x of a) total += x[kunci] as number;
  return total;
}
const gula: Barang = { nama: "Gula", stok: 5, harga: 14000 };
const beras: Barang = { nama: "Beras", stok: 12, harga: 13000 };
console.log(ambil(gula, "nama"), ambil(gula, "stok"));
console.log(ambil(gula, "harga") * ambil(gula, "stok"));
console.log(totalKolom([gula, beras], "stok"));

