function termurah<T extends { harga: number }>(a: T[]): T | undefined {
  let hasil: T | undefined = undefined;
  for (const x of a) {
    if (hasil === undefined || x.harga < hasil.harga) hasil = x;
  }
  return hasil;
}
const produk = [
  { nama: "Kopi", harga: 18000 },
  { nama: "Teh", harga: 12000 },
  { nama: "Jus", harga: 15000 },
];
const paket = [
  { kode: "P1", harga: 50000 },
  { kode: "P2", harga: 45000 },
];
console.log(termurah(produk)?.nama);
console.log(termurah(paket)?.kode);
